const body = $input.first().json;
const payload = body.payload || body;

const attendees = payload.attendees || [];
const organizer = payload.organizer || {};
const cliente = attendees.find(a => a.email !== organizer.email) || attendees[0] || {};

const booking_id = String(payload.uid || payload.bookingUid || payload.id || Date.now());
const cliente_nombre = (cliente.name || payload.responses?.name?.value || '').trim();
const email = (cliente.email || payload.responses?.email?.value || '').toLowerCase().trim();
const telefonoRaw = (
  payload.responses?.phone?.value ||
  payload.responses?.phone_number?.value ||
  payload.metadata?.phone || ''
);
const telefono = telefonoRaw.replace(/\s+/g, '').replace(/^00/, '+');
const servicio = (payload.eventTitle || payload.title || payload.type || 'Consulta Audivisión').trim();

return [{
  json: {
    booking_id,
    cliente_nombre,
    telefono,
    email,
    servicio,
    fecha_inicio: payload.startTime || '',
    fecha_fin: payload.endTime || '',
    estado: 'CONFIRMADA',
    sms_enviado: 'FALSE',
    resena_enviada: 'FALSE'
  }
}];

const ahora = new Date();
const resultados = [];

for (const item of $input.all()) {
  const row = item.json;
  if (['true','TRUE','1',true,'Verdadero'].includes(row.sms_enviado)) continue;
  if (!row.telefono || !row.booking_id) continue;
  const fechaCita = new Date(row.fecha_inicio);
  if (isNaN(fechaCita.getTime())) continue;
  const diffHoras = (fechaCita - ahora) / (1000 * 60 * 60);
  if (diffHoras >= 23 && diffHoras <= 25) {
    resultados.push({ json: { ...row } });
  }
}

return resultados;

const row = $input.first().json;

const fechaFormateada = new Date(row.fecha_inicio).toLocaleString('es-ES', {
  timeZone: 'Europe/Madrid',
  weekday: 'long', day: '2-digit', month: 'long',
  hour: '2-digit', minute: '2-digit'
});

const fallback = `Hola ${row.cliente_nombre}, recuerda tu cita en Audivisión: ${row.servicio} el ${fechaFormateada}. Gestión: ${$env.CALCOM_BOOKING_LINK}`;

try {
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + $env.OPENAI_API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'gpt-4o-mini',
      max_tokens: 180,
      messages: [
        {
          role: 'system',
          content: 'Eres el asistente de Audivisión, clínica de audiología en España. Escribes mensajes breves, cálidos y profesionales.'
        },
        {
          role: 'user',
          content: `Escribe un SMS de recordatorio de cita. Máximo 155 caracteres. Sin emojis. Incluye nombre, servicio, fecha y link al final.\n\nPaciente: ${row.cliente_nombre}\nServicio: ${row.servicio}\nFecha: ${fechaFormateada}\nLink: ${$env.CALCOM_BOOKING_LINK}\n\nResponde SOLO con el texto del SMS.`
        }
      ]
    })
  });
  const data = await res.json();
  const mensaje = (data.choices?.[0]?.message?.content || '').trim().substring(0, 160);
  return [{ json: { ...row, mensaje_sms: mensaje || fallback } }];
} catch (e) {
  return [{ json: { ...row, mensaje_sms: fallback } }];
}

const ahora = new Date();
const resultados = [];

for (const item of $input.all()) {
  const row = item.json;
  if (['true','TRUE','1',true,'Verdadero'].includes(row.resena_enviada)) continue;
  if (!row.telefono || !row.booking_id) continue;
  const fechaCita = new Date(row.fecha_inicio);
  if (isNaN(fechaCita.getTime())) continue;
  const diffHoras = (fechaCita - ahora) / (1000 * 60 * 60);
  if (diffHoras >= -25 && diffHoras <= -23) {
    resultados.push({ json: { ...row } });
  }
}

return resultados;

