const error = $input.first().json;

const workflowName = error.workflow?.name || 'Audivisión';
const nodeName = error.node?.name || 'Nodo desconocido';
const errorMsg = error.error?.message || error.message || 'Sin mensaje';
const errorStack = (error.error?.stack || '').substring(0, 500);
const execId = error.execution?.id || 'N/A';

const timestamp = new Date().toLocaleString('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit'
});

const mensajeTelegram = [
  '⚠️ <b>Error en Audivisión</b>',
  '',
  `📌 <b>Workflow:</b> ${workflowName}`,
  `🔴 <b>Nodo:</b> ${nodeName}`,
  `❌ <b>Error:</b> ${errorMsg}`,
  `🕐 <b>Hora:</b> ${timestamp}`,
  `🆔 <b>Ejecución:</b> ${execId}`
].join('\n');

return [{
  json: {
    workflow_name: workflowName,
    nodo_nombre: nodeName,
    mensaje_error: errorMsg,
    stack_trace: errorStack,
    timestamp,
    mensaje_telegram: mensajeTelegram
  }
}];
